import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CFOYCmPM.js";const m=JSON.parse('{"title":"Chapter 6: Economy, Custom Currency, Traders & Factions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/economy-and-factions.md","filePath":"guide/economy-and-factions.md","lastUpdated":null}'),i={name:"guide/economy-and-factions.md"};function n(l,e,s,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="chapter-6-economy-custom-currency-traders-factions" tabindex="-1">Chapter 6: Economy, Custom Currency, Traders &amp; Factions <a class="header-anchor" href="#chapter-6-economy-custom-currency-traders-factions" aria-label="Permalink to &quot;Chapter 6: Economy, Custom Currency, Traders &amp; Factions&quot;">​</a></h1><p>Transform your server into a thriving world with trading hubs, survival economies, faction territories, and custom loot tiers.</p><hr><h2 id="💵-built-in-vanilla-dollar-currency-1-to-100" tabindex="-1">💵 Built-in Vanilla Dollar Currency ($1 to $100) <a class="header-anchor" href="#💵-built-in-vanilla-dollar-currency-1-to-100" aria-label="Permalink to &quot;💵 Built-in Vanilla Dollar Currency ($1 to $100)&quot;">​</a></h2><p>DayZ Studio includes a complete physical currency system implemented as 100% vanilla inventory items:</p><ul><li><code>DSQ_Dollar1</code> ($1 bill)</li><li><code>DSQ_Dollar5</code> ($5 bill)</li><li><code>DSQ_Dollar10</code> ($10 bill)</li><li><code>DSQ_Dollar20</code> ($20 bill)</li><li><code>DSQ_Dollar50</code> ($50 bill)</li><li><code>DSQ_Dollar100</code> ($100 bill)</li></ul><h3 id="currency-highlights" tabindex="-1">Currency Highlights <a class="header-anchor" href="#currency-highlights" aria-label="Permalink to &quot;Currency Highlights&quot;">​</a></h3><ul><li><strong>Zero Mod Dependencies:</strong> Uses standard DayZ engine item mechanics.</li><li><strong>Stackable &amp; Splitable:</strong> Bills stack up to 1,000 per inventory slot and can be split into smaller denominations just like rags or ammunition.</li><li><strong>Custom Bill Art:</strong> Drop your own custom <code>.paa</code> or <code>.png</code> bill textures into <code>Documents\\DayZStudio\\Assets\\Currency</code> to have your server&#39;s custom currency minted automatically!</li></ul><hr><h2 id="🛒-building-an-npc-trader-store" tabindex="-1">🛒 Building an NPC Trader Store <a class="header-anchor" href="#🛒-building-an-npc-trader-store" aria-label="Permalink to &quot;🛒 Building an NPC Trader Store&quot;">​</a></h2><ol><li>Open the <strong>NPCs Tab</strong> (<code>Alt + 5</code>) and select any character.</li><li>Check <strong>Enable Trader Store</strong>.</li><li>In the trader inspector: <ul><li>Click <strong>+ Add Item to Catalog</strong>.</li><li>Select items from your game classes (e.g., <code>M4A1</code>, <code>Mag_STANAG_30Rnd</code>, <code>CannedPeaches</code>).</li><li>Set <strong>Buy Price</strong> (what players pay) and <strong>Sell Price</strong> (what the trader pays players).</li><li>Set stock caps and restock timers.</li><li>Attach standing requirements (e.g., <em>&quot;Requires Friendly Military Standing&quot;</em>).</li></ul></li></ol><hr><h2 id="🏳️-faction-reputation-system-1000-to-1000" tabindex="-1">🏳️ Faction Reputation System (-1000 to +1000) <a class="header-anchor" href="#🏳️-faction-reputation-system-1000-to-1000" aria-label="Permalink to &quot;🏳️ Faction Reputation System (-1000 to +1000)&quot;">​</a></h2><p>DayZ Studio features a multi-tiered reputation framework:</p><ul><li><strong>Survivors:</strong> Default friendly/neutral faction.</li><li><strong>Military:</strong> Law-enforcement faction guarding high-tier zones.</li><li><strong>Bandits:</strong> Hostile outlaws.</li></ul><h3 id="automated-karma-triggers" tabindex="-1">Automated Karma Triggers <a class="header-anchor" href="#automated-karma-triggers" aria-label="Permalink to &quot;Automated Karma Triggers&quot;">​</a></h3><ul><li>Killing infected grants <code>+5 Survivor Reputation</code>.</li><li>Killing unarmed survivors inflicts <code>-100 Survivor Reputation</code> (turning players into Bandits).</li><li>Armed faction guards automatically raise weapons and attack players who enter their outposts with <strong>Hostile</strong> reputation!</li></ul><hr><h2 id="🎒-visual-loot-zones-central-economy" tabindex="-1">🎒 Visual Loot Zones &amp; Central Economy <a class="header-anchor" href="#🎒-visual-loot-zones-central-economy" aria-label="Permalink to &quot;🎒 Visual Loot Zones &amp; Central Economy&quot;">​</a></h2><p>Want to configure your new base to spawn high-tier snipers and tactical gear?</p><ol><li>In the <strong>Map View</strong>, switch to the <strong>Loot &amp; Zones</strong> tool.</li><li>Select your brush: <strong>Polygon</strong>, <strong>Rectangle</strong>, or <strong>Circle</strong>.</li><li>Draw a perimeter around your base.</li><li>Assign the loot tier: <strong>Tier 3</strong> or <strong>Tier 4 (High Military)</strong>.</li><li>Studio automatically writes and updates <code>mapgrouppos.xml</code> and <code>areaflags.map</code>—eliminating the need to hand-edit thousands of lines of raw XML!</li></ol>',21)])])}const h=t(i,[["render",n]]);export{m as __pageData,h as default};
